from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Convert each property array to a set to easily find the number of distinct common integers
        sets = [set(row) for row in properties]

        parent = list(range(n))
        components = n

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        for i in range(n):
            for j in range(i + 1, n):
                px = find(i)
                py = find(j)
                # If they are already in the same component, we skip the intersection check
                if px != py and len(sets[i] & sets[j]) >= k:
                    parent[px] = py
                    components -= 1

        return components
